ALTER TABLE `crmClients` ADD `birthDate` timestamp;
CREATE TABLE `agentPolicies` (`id` int AUTO_INCREMENT NOT NULL,`agentEmail` varchar(320) NOT NULL,`clientId` int,`clientName` varchar(255) NOT NULL,`clientEmail` varchar(320),`clientPhone` varchar(30),`birthDate` timestamp,`policyNumber` varchar(100) NOT NULL,`product` varchar(120),`premiumAmount` decimal(12,2) DEFAULT '0.00',`premiumFrequency` varchar(50),`coverageAmount` decimal(14,2) DEFAULT '0.00',`beneficiaries` text,`issuedAt` timestamp,`createdAt` timestamp NOT NULL DEFAULT (now()),`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT `agentPolicies_id` PRIMARY KEY(`id`));
CREATE TABLE `agentTasks` (`id` int AUTO_INCREMENT NOT NULL,`agentEmail` varchar(320) NOT NULL,`clientId` int,`title` varchar(255) NOT NULL,`dueAt` timestamp,`status` enum('pending','completed') NOT NULL DEFAULT 'pending',`createdAt` timestamp NOT NULL DEFAULT (now()),CONSTRAINT `agentTasks_id` PRIMARY KEY(`id`));
CREATE TABLE `scheduledMessages` (`id` int AUTO_INCREMENT NOT NULL,`agentEmail` varchar(320) NOT NULL,`clientId` int,`occasion` enum('birthday','christmas','new_year','custom') NOT NULL DEFAULT 'custom',`channel` enum('email','sms','whatsapp') NOT NULL,`message` text NOT NULL,`scheduledAt` timestamp,`isActive` int NOT NULL DEFAULT 1,`createdAt` timestamp NOT NULL DEFAULT (now()),CONSTRAINT `scheduledMessages_id` PRIMARY KEY(`id`));
